+              <text x="${margin.left + w + 10}" y="${y + actualBarH / 2 + 4}" text-anchor="start" font-size="12" fill="rgba(255,255,255,0.68)">${esc(
+                rightLabelFn ? rightLabelFn(r) : String(v)
+              )}</text>
+            </g>`;
+        });
+
+        const gridSvg = grid
+          .map(
+            (g, i) => `
+              <g opacity="${i === gridLines ? 0.25 : 0.18}">
+                <line x1="${g.x}" y1="${margin.top}" x2="${g.x}" y2="${height - margin.bottom}" stroke="rgba(255,255,255,0.35)" stroke-width="1" />
+                <text x="${g.x}" y="${height - 8}" text-anchor="middle" font-size="11" fill="rgba(255,255,255,0.45)">${esc(
+                  (i === gridLines ? maxV : g.v).toFixed(i === gridLines ? 0 : 0)
+                )}</text>
+              </g>`
+          )
+          .join("");
+
+        const header = `
+          <text x="${margin.left}" y="22" font-size="14" fill="rgba(255,255,255,0.92)" font-weight="600">${esc(
