+            tip.style.display = "block";
+            const rect = container.getBoundingClientRect();
+            const x = e.clientX - rect.left + 14;
+            const y = e.clientY - rect.top + 14;
+            tip.style.left = `${x}px`;
+            tip.style.top = `${y}px`;
+          });
+          g.addEventListener("mouseleave", () => {
+            tip.style.display = "none";
+          });
+        }
+      }
