+      function groupBy(array, keyFn) {
+        const map = new Map();
+        for (const item of array) {
+          const k = keyFn(item);
+          const bucket = map.get(k);
+          if (bucket) bucket.push(item);
+          else map.set(k, [item]);
+        }
