+        const innerW = width - margin.left - margin.right;
+        const innerH = height - margin.top - margin.bottom;
+        const maxV = Math.max(...rows.map((r) => r[valueKey]));
+        const barH = innerH / Math.max(rows.length, 1);
+        const pad = clamp(barH * 0.18, 2, 10);
+        const actualBarH = barH - pad;
+
+        const gridLines = 5;
+        const grid = [];
+        for (let i = 0; i <= gridLines; i++) {
+          const t = i / gridLines;
+          const x = margin.left + t * innerW;
+          const v = t * maxV;
+          grid.push({ x, v });
+        }
+
+        let bars = "";
+        rows.forEach((r, i) => {
+          const v = r[valueKey];
+          const w = (v / maxV) * innerW;
+          const y = margin.top + i * barH + pad / 2;
+          const color = colorFn ? colorFn(r, i) : "#7dd3fc";
+
+          const tooltipLines = tooltipLinesFn ? tooltipLinesFn(r) : [];
+          const tooltip = esc([r[labelKey], ...tooltipLines].join("\n"));
