+              <rect x="${margin.left}" y="${y}" width="${Math.max(2, w)}" height="${actualBarH}" rx="6" fill="${color}" opacity="0.92" />
+              <text x="${margin.left - 10}" y="${y + actualBarH / 2 + 4}" text-anchor="end" font-size="12" fill="rgba(255,255,255,0.78)">${esc(
